import{_ as s,o as a,c as t,a3 as n}from"./chunks/framework.Cr9EE2ob.js";const u=JSON.parse(`{"title":"Other users' mailboxes","description":"A user can open another user's mailboxes under a namespace such as user/alice/, when alice's ACL allows it. The namespace is configured once, and yarilo…","frontmatter":{"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/storage/owner_shared_ns.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/storage/owner_shared_ns.html"}],["meta",{"property":"og:title","content":"Other users' mailboxes"}],["meta",{"name":"twitter:title","content":"Other users' mailboxes"}],["meta",{"property":"og:description","content":"A user can open another user's mailboxes under a namespace such as user/alice/, when alice's ACL allows it. The namespace is configured once, and yarilo…"}],["meta",{"name":"twitter:description","content":"A user can open another user's mailboxes under a namespace such as user/alice/, when alice's ACL allows it. The namespace is configured once, and yarilo…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/storage/owner_shared_ns.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/storage/owner_shared_ns.html\\",\\"headline\\":\\"Other users' mailboxes\\",\\"description\\":\\"A user can open another user's mailboxes under a namespace such as user/alice/, when alice's ACL allows it. The namespace is configured once, and yarilo…\\",\\"dateModified\\":\\"2026-10-22T19:41:46.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Other users' mailboxes\\",\\"item\\":\\"https://doc.yarilomail.org/main/storage/owner_shared_ns.html\\"}]}]}"]]},"headers":[],"relativePath":"storage/owner_shared_ns.md","filePath":"storage/owner_shared_ns.md","lastUpdated":1792698106000}`),i={name:"storage/owner_shared_ns.md"};function o(r,e,l,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="other-users-mailboxes" tabindex="-1">Other users&#39; mailboxes <a class="header-anchor" href="#other-users-mailboxes" aria-label="Permalink to &quot;Other users&#39; mailboxes&quot;">​</a></h1><p>A user can open another user&#39;s mailboxes under a namespace such as <code>user/<wbr>alice/</code>, when alice&#39;s ACL allows it. The namespace is configured once, and yarilo resolves each owner&#39;s storage the first time a session names that owner.</p><p>For namespaces in general, see <a href="/main/storage/namespace.html">Namespaces</a>.</p><h2 id="configuring-the-namespace" tabindex="-1">Configuring the namespace <a class="header-anchor" href="#configuring-the-namespace" aria-label="Permalink to &quot;Configuring the namespace&quot;">​</a></h2><p>Add a namespace whose prefix carries the owner variable <code>%u</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaces</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shared</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # or other, for the Other Users slot of NAMESPACE</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user/%u/&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    separator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;maildir:%h&quot;</span></span></code></pre></div><p>The <code>%u</code> in the prefix makes this namespace owner-templated. Inside it, the variables <code>%h</code>, <code>%u</code>, <code>%n</code> and <code>%d</code> in <code>location</code> stand for the owner of the mailbox, not for the user who is logged in.</p><p>yarilo refuses to start, naming the namespace, when an owner-templated entry:</p><ul><li>has no <code>location</code>, or a <code>location</code> without one of those variables, which would put every owner at one path;</li><li>sets <code>subscriptions: true</code> (subscriptions to other users&#39; folders are kept with the subscriber);</li><li>sets <code>list: yes</code> (the unexpanded <code>user/<wbr>%u</code> is not a mailbox; leave <code>list</code> unset or set <code>children</code>);</li><li>has anything after <code>%u</code> other than the separator. <code>user/<wbr>%u/</code> works; <code>user/<wbr>%n@%d/</code> does not.</li></ul><h2 id="how-an-owner-s-storage-is-found" tabindex="-1">How an owner&#39;s storage is found <a class="header-anchor" href="#how-an-owner-s-storage-is-found" aria-label="Permalink to &quot;How an owner&#39;s storage is found&quot;">​</a></h2><p>When a session names <code>user/<wbr>alice/<wbr>Sent</code>, yarilo looks alice up in the userdb, exactly as at her own login. Her userdb entry decides the driver and the path. The namespace <code>location</code> is used only when the userdb gives no mail location for her.</p><ul><li>The owner segment is only ever a userdb key, never part of a path. An owner who is not in the userdb is a mailbox that does not exist.</li><li><code>user/<wbr>&lt;own name&gt;/<wbr>…</code> opens the user&#39;s own mailboxes.</li><li>A session keeps up to 64 owners open. Past that one is closed, and naming it again costs one more userdb lookup.</li></ul><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access control&quot;">​</a></h2><p>The owner has full rights on their own mailboxes, whatever the ACL says, so no ACL entry can lock an owner out.</p><p>Anyone else needs ACL rights, as for any shared mailbox:</p><ul><li><code>l</code> to see the mailbox in <code>LIST</code>;</li><li><code>r</code> to select it;</li><li><code>i</code> to append and <code>p</code> to deliver into it.</li></ul><p>A user without <code>l</code> gets the same answer as for a mailbox that does not exist, so names in someone else&#39;s space cannot be probed. With <code>l</code>, the refusal names the missing right.</p><p>The first mailbox in an empty space needs the create right granted on the namespace root (<code>--root</code> in <code>yarctl</code>). Each new mailbox gets an ACL file of its own, copied from its parent, or from the root, when it is created. Later changes to the parent do not reach it.</p><p>Within one ACL file, when two lines name the same identifier with the same sign, the later line counts. A malformed line makes the whole file unreadable, and the mailbox refuses access rather than serving part of its ACL.</p><h2 id="listing-other-users" tabindex="-1">Listing other users <a class="header-anchor" href="#listing-other-users" aria-label="Permalink to &quot;Listing other users&quot;">​</a></h2><p><code>LIST &quot;&quot; &quot;user/<wbr>*&quot;</code> shows the owners who have granted the user anything. They are read from a registry kept in the dict that <code>acl.<wbr>acl_<wbr>sharing_<wbr>map</code> names; that dict must be in the <code>dicts</code> section. Without it <code>user/<wbr>*</code> lists nobody, while a name written out, such as <code>user/<wbr>alice/<wbr>*</code>, still works.</p><p>The registry is re-read once an hour:</p><ul><li>After a <code>SETACL</code>, the user it names sees the new owner on their next <code>LIST</code> when they are on the same backend, and within an hour on the others.</li><li><code>yarctl backend acl registry rebuild &lt;owner&gt; --namespace &lt;prefix&gt;</code> rewrites an owner&#39;s rows and drops every cached answer.</li><li><code>yarctl backend acl registry list &lt;user&gt;</code> reads the registry directly, without the cache.</li></ul><p><code>NAMESPACE</code> advertises the prefix as <code>user/</code>, which is what a client prepends to an owner&#39;s name.</p><h2 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h2><p>LMTP and Sieve <code>fileinto</code> can deliver to <code>user/<wbr>alice/<wbr>&lt;folder&gt;</code> when the recipient holds <code>p</code> on it.</p><p>When that delivery cannot be made, the message goes to the recipient&#39;s own INBOX and a warning is logged. This covers an unknown owner, a missing right, and storage that cannot be opened. No mail is lost.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>The owner&#39;s files must be on storage that the backend serving the session mounts.</p><h3 id="routing-within-a-farm-users-who-share-must-land-on-one-backend" tabindex="-1">Users who share must land on one backend <a class="header-anchor" href="#routing-within-a-farm-users-who-share-must-land-on-one-backend" aria-label="Permalink to &quot;Users who share must land on one backend {#routing-within-a-farm-users-who-share-must-land-on-one-backend}&quot;">​</a></h3><p>When all backends of a director tag share one volume, any of them can open any owner&#39;s files. When each backend has its own storage, the owner&#39;s mailbox is simply not on the backend serving the other user. Every share then fails in a way that looks like an ACL fault.</p><p>The director hashes the whole address by default (<code>director_<wbr>service.<wbr>username_<wbr>hash</code> unset, i.e. <code>%Lu</code>), so two users of one domain routinely land on different backends.</p><p>If users of one domain share mailboxes with each other, route the domain to one backend:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    assignment_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">domain</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one backend per domain, picked by load</span></span></code></pre></div><p>The domain is placed on the backend with the fewest connections, and every user of it follows. The policy does not read <code>username_<wbr>hash</code>.</p><p>Hashing the domain does the same and stays supported:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username_hash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%Ld&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # hash the domain, not the address</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    assignment_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # least_sessions never reads the name</span></span></code></pre></div><p>Both lines are needed: <code>least_<wbr>sessions</code> picks the least-loaded backend and ignores the hash template. The difference is where the domain lands: <code>hash</code> decides by name, <code>domain</code> by load. The default stays <code>%Lu</code>, because hashing a single-domain deployment on <code>%Ld</code> puts every account on one backend.</p><h3 id="owners-on-another-storage-shard" tabindex="-1">Owners on another storage shard <a class="header-anchor" href="#owners-on-another-storage-shard" aria-label="Permalink to &quot;Owners on another storage shard&quot;">​</a></h3><p>Access to an owner whose mailbox is on another director tag, and so on storage this backend does not mount, is not supported.</p><h2 id="what-a-user-sees-when-access-fails" tabindex="-1">What a user sees when access fails <a class="header-anchor" href="#what-a-user-sees-when-access-fails" aria-label="Permalink to &quot;What a user sees when access fails&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Situation</th><th style="text-align:left;">IMAP</th><th style="text-align:left;">LMTP</th></tr></thead><tbody><tr><td style="text-align:left;">Owner not in the userdb</td><td style="text-align:left;"><code>NO</code>, the mailbox does not exist</td><td style="text-align:left;">recipient&#39;s INBOX, warning logged</td></tr><tr><td style="text-align:left;">Owner&#39;s storage not mounted here</td><td style="text-align:left;"><code>NO</code></td><td style="text-align:left;">recipient&#39;s INBOX, warning logged</td></tr><tr><td style="text-align:left;">User holds <code>l</code> but lacks the right needed</td><td style="text-align:left;"><code>NO [NOPERM]</code>, naming the right</td><td style="text-align:left;">recipient&#39;s INBOX, warning logged</td></tr><tr><td style="text-align:left;">User holds no <code>l</code></td><td style="text-align:left;"><code>NO [NONEXISTENT]</code>, as for an absent mailbox</td><td style="text-align:left;">recipient&#39;s INBOX, warning logged</td></tr><tr><td style="text-align:left;">The owner is the user</td><td style="text-align:left;">the user&#39;s own mailboxes</td><td style="text-align:left;">the recipient&#39;s own store</td></tr></tbody></table>`,42)])])}const m=s(i,[["render",o]]);export{u as __pageData,m as default};
